def solve(shapes, dots, strict=True):
    FULL=(1<<len(dots))-1
    cs={k:cands2(v,dots,strict) for k,v in shapes.items()}
    keys=list(cs)
    sols=[]
    def rec(idx, mask, cost, plan):
        if mask==FULL or idx==len(keys):
            if mask==FULL: sols.append((cost, tuple(plan)))
            return
        # prune: remaining coverage possible?
        rem=0
        for k in keys[idx:]:
            for m in cs[k]: rem|=m
        if (mask|rem)!=FULL: return
        for m,(t,c) in cs[keys[idx]].items():
            rec(idx+1, mask|m, cost+c, plan+[(keys[idx],t,bin(m),c)])
    rec(0,0,0,[])
    sols.sort(key=lambda s:s[0])
    return sols
